{
  "message": "Thanks — I tried to look up cards for BA-7392041 but the system returned: \"Account 'BA-7392041' not found.\"",
  "what_this_means": "That usually means the account ID was mistyped, the account ID in the app is different than the one you copied, or the account is under a different internal ID format.",
  "next_steps": [
    "Please double-check the account ID in the app (Accounts → Blue Account → Account details) and paste it here exactly as shown. I can wait while you do that.",
    "If you prefer not to copy the account ID again, you can instead paste the card's full internal card_id (if visible) or the full 16‑digit card number — I can use that to find the card record. (Only provide that if you’re comfortable.)",
    "If you'd rather not share either, try one of these immediate workarounds at the register while I wait:",
    "- Ask the merchant to run the card as signature/credit instead of chip/PIN.",
    "- Try contactless/tap if available or a different terminal/register.",
    "- Try a small auth (e.g., $1) to test authorization.",
    "- Use a mobile wallet if the card is added there."
  ],
  "note_about_velocity_block": "If this is a velocity block (multiple rapid purchases), I can clear it for you once I locate the card record. Because you are already verified, I will then call the system to clear a velocity block with reason = \"velocity_clear\" and it will take effect immediately.",
  "options": [
    {
      "label": "Re-check account ID and paste it",
      "action": "paste_account_id"
    },
    {
      "label": "Provide card internal ID or full card number",
      "action": "paste_card_id_or_full_number"
    },
    {
      "label": "I prefer to try merchant workarounds first",
      "action": "try_workarounds"
    },
    {
      "label": "Transfer to human agent now",
      "action": "transfer_to_human_agents"
    }
  ],
  "ask": "Which option would you like to do?"
}
